//! Per-format registry lookup: `kind -> &FormatKind` (read/write/corpus/layout).
//!
//! Each format crate exposes its connectors as a referenced `pub static
//! FORMAT_KINDS: &[FormatKind]` (generated by its `build.rs` from `src/metadata/*.rs`,
//! DCE-safe — see `formats-xml::registry`). The pipeline indexes a format's slice into a
//! `BTreeMap<&str, &FormatKind>` for O(log n) `kind` lookup, deterministically ordered.
//!
//! cf (M3 — cf as a SOURCE) IS wired: `Format::Cf` maps to `formats_cf::metadata::
//! FORMAT_KINDS`. Its rows use `CorpusLayout::Container { kind_code, body_arity,
//! ident_arity }` (records INSIDE one `.cf` container), not file-per-object — so the cf
//! READ path ([`crate::cf`]) is container-based, not a directory walk. The registry lookup
//! itself is layout-agnostic (`kind -> &FormatKind`); only enumeration differs by layout.

use std::collections::BTreeMap;

use formats_xml::registry::{Format, FormatKind};

use crate::ConvertError;

/// A format's connectors indexed by canonical kind code.
///
/// Built from the format crate's `FORMAT_KINDS` static; holds `'static` references into
/// it (the slice lives for the program). Lookup is by `kind` (`obj.kind.as_str()`).
#[derive(Debug, Clone)]
pub struct FormatRegistry {
    format: Format,
    by_kind: BTreeMap<&'static str, &'static FormatKind>,
}

impl FormatRegistry {
    /// The registry for `format` (EDT / Designer / cf). All three resolve to that format
    /// crate's referenced `FORMAT_KINDS` static. cf rows carry `Container` layout; the
    /// registry is layout-agnostic — the cf READ path enumerates records from the container
    /// rather than walking directories (see [`crate::cf`]).
    pub fn for_format(format: Format) -> Result<Self, ConvertError> {
        let rows: &'static [FormatKind] = match format {
            Format::Edt => formats_edt::metadata::FORMAT_KINDS,
            Format::Designer => formats_designer::metadata::FORMAT_KINDS,
            Format::Cf => return Err(ConvertError::FormatNotSupported("CF excluded from source-only adapter".into())),
        };
        Ok(Self::from_rows(format, rows))
    }

    /// Build from an explicit slice (testable; used by [`Self::for_format`]).
    fn from_rows(format: Format, rows: &'static [FormatKind]) -> Self {
        let mut by_kind: BTreeMap<&'static str, &'static FormatKind> = BTreeMap::new();
        for fk in rows {
            debug_assert_eq!(fk.format, format, "FORMAT_KINDS row format must match");
            by_kind.insert(fk.kind, fk);
        }
        FormatRegistry { format, by_kind }
    }

    /// The format this registry serves.
    pub fn format(&self) -> Format {
        self.format
    }

    /// The connector for `kind`, if this format has one.
    pub fn get(&self, kind: &str) -> Option<&'static FormatKind> {
        self.by_kind.get(kind).copied()
    }

    /// All connector rows, deterministically ordered by kind code.
    pub fn iter(&self) -> impl Iterator<Item = &'static FormatKind> + '_ {
        self.by_kind.values().copied()
    }

    /// The canonical root kind code (the SingletonFile config root). Exactly one row uses
    /// a `SingletonFile` layout; that is the root. `None` if (unexpectedly) none does.
    pub fn root_kind(&self) -> Option<&'static FormatKind> {
        self.by_kind.values().copied().find(|fk| {
            matches!(
                fk.layout,
                formats_xml::registry::CorpusLayout::SingletonFile { .. }
            )
        })
    }
}
